<?php // Both printable surfaces consume the same groups/numbering, never reselect questions.
$isLearningPaper=$isLearningPaper??false;$paperFormat=$paperFormat??paperFormatInput([]); ?>
<div class="alert alert-success no-print" role="status"><?= $isLearningPaper?'Test paper':'Exam paper' ?> generated successfully: <?= count($paper['questions']) ?> <?= $isLearningPaper?'questions':'question items' ?>, <?= learningDecimalString($paper['total_units']) ?> marks. Required question time: <?= learningDecimalString($paper['required_units']) ?> minutes.</div>
<div class="no-print d-flex flex-wrap align-items-center gap-2 mb-3"><label for="<?= $isLearningPaper?'testPrintLanguage':'examPrintLanguage' ?>">Print language</label><select id="<?= $isLearningPaper?'testPrintLanguage':'examPrintLanguage' ?>" class="form-select w-auto" data-exam-language-control><?php foreach(examQuestionLanguages() as $key=>$label): ?><option value="<?= $key ?>" <?= $questionLanguage===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button type="button" class="btn btn-primary" data-exam-print="questions">Print <?= $isLearningPaper?'Test':'Exam' ?> Paper</button><button type="button" class="btn btn-outline-primary" data-exam-print="answers">Print Answer Key</button></div>
<section id="examQuestionSheet" class="exam-paper card card-body mb-4">
<?= paperFormatHeader($paperFormat,$school,$title,$className,$subjectName,$paper) ?>
<?php foreach($paperGroups as $group): ?><?php if($group['label']!==''): ?><h4 class="exam-section-title"><?= sanitize($group['label']) ?> <span><?= sanitize($group['calculation']) ?></span></h4><?php endif; ?>
<?php if($group['type']==='MCQ'): ?><p><strong>1. Multiple-choice questions</strong></p><?php endif; ?>
<?php foreach($group['items'] as $item): $q=$item['question']; ?><div class="exam-question" data-exam-question-id="<?= (int)$q['id'] ?>" data-question-id="<?= (int)$q['id'] ?>"><div class="exam-question-heading"><strong><?= $item['sub_no']!==null?'('.$item['sub_no'].')':$item['main_no'].'.' ?></strong><div><?= examQuestionRichVariants($q['question_text'],$q['question_text_np']??'',$questionLanguage,true) ?></div><?php if(!examQuestionHasParts($q)): ?><span>[<?= learningDecimalString($q['marks_units']) ?>]</span><?php endif; ?></div>
<?php if($q['type']==='MCQ'): $en=json_decode($q['options']??'{}',true)?:[];$np=json_decode($q['options_np']??'{}',true)?:[]; ?><div class="exam-mcq-options"><?php foreach(['A','B','C','D'] as $o): ?><div><strong><?= strtolower($o) ?>.</strong> <?= examQuestionRichVariants($en[$o]??'',$np[$o]??'',$questionLanguage) ?></div><?php endforeach; ?></div><?php endif; ?></div><?php endforeach;endforeach; ?>
</section>
<section id="examAnswersSheet" class="exam-paper card card-body mb-4"><?= paperFormatHeader($paperFormat,$school,$title,$className,$subjectName,$paper) ?><h2>Answer Key — <?= sanitize($title) ?></h2>
<?php foreach($paperGroups as $group): ?><?php if($group['label']!==''): ?><h3 class="exam-section-title"><?= sanitize($group['label']) ?> <span><?= sanitize($group['calculation']) ?></span></h3><?php endif; ?>
<?php foreach($group['items'] as $item): $q=$item['question']; ?><article class="exam-question" data-exam-question-id="<?= (int)$q['id'] ?>" data-question-id="<?= (int)$q['id'] ?>"><div class="exam-question-heading"><strong><?= $item['main_no'].'.'.($item['sub_no']!==null?' ('.$item['sub_no'].')':'') ?></strong><div><?php if($q['type']==='MCQ'): ?><p>Correct option: <strong><?= sanitize($q['correct_option']) ?></strong></p><?php endif; ?>
<?php if(!questionImportHasContent($q['answer']??'')&&!questionImportHasContent($q['answer_np']??'')): ?><p class="text-muted">No model answer supplied; prepare the marking guide before assessment.</p><?php else: ?><?= examQuestionRichVariants($q['answer']??'',$q['answer_np']??'',$questionLanguage) ?><?php endif; ?><?= examQuestionAnswerMarks($q) ?></div></div></article><?php endforeach;endforeach; ?></section>
<details class="no-print card card-body"><summary>Allocation audit</summary><p>Questions retain their stored marks. Estimated times are planning data, not official marking rules.</p><div class="table-responsive"><table class="table"><thead><tr><th>Allocation / grid row</th><th>Type</th><th>Questions</th><th>Marks</th></tr></thead><tbody><?php foreach($paper['rows'] as $row): ?><tr><td><?= sanitize($row['name']) ?></td><td><?= sanitize($row['type']) ?></td><td><?= (int)$row['count'] ?></td><td><?= sanitize($row['total_marks']) ?></td></tr><?php endforeach; ?></tbody></table>
<table class="table"><thead><tr><th>Chapter</th><th>Questions</th><th>Marks</th></tr></thead><tbody><?php foreach($paper['chapter_counts'] as $ch=>$n): ?><tr><td><?= sanitize($ch) ?></td><td><?= $n ?></td><td><?= learningDecimalString($paper['chapter_units'][$ch]??0) ?></td></tr><?php endforeach; ?></tbody></table></div></details>
